"""Heat diffusion on a grid, with the stencil computed by a wgpu compute shader."""

import sys

import numpy as np
import wgpu

WORKGROUP = 8

SHADER = f"""
struct Dims {{
    width: u32,
    height: u32,
}};

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size({WORKGROUP}, {WORKGROUP})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {{
    let x = gid.x;
    let y = gid.y;
    let w = dims.width;
    let h = dims.height;
    if (x >= w || y >= h) {{
        return;
    }}
    let xl = select(x - 1u, x, x == 0u);
    let xr = min(x + 1u, w - 1u);
    let yu = select(y - 1u, y, y == 0u);
    let yd = min(y + 1u, h - 1u);
    let row = y * w;
    let total = 4u * src[row + x]
        + src[row + xl]
        + src[row + xr]
        + src[yu * w + x]
        + src[yd * w + x];
    dst[row + x] = total / 8u;
}}
"""


def parse(text):
    tokens = text.split()
    if len(tokens) < 3:
        raise ValueError("header must hold width, height and steps")
    width, height, steps = (int(t) for t in tokens[:3])
    if not (1 <= width <= 512 and 1 <= height <= 512):
        raise ValueError("width and height must be between 1 and 512")
    if not (0 <= steps <= 1000):
        raise ValueError("steps must be between 0 and 1000")
    cells = tokens[3:]
    if len(cells) != width * height:
        raise ValueError(f"expected {width * height} cells, found {len(cells)}")
    grid = np.array([int(c) for c in cells], dtype=np.int64)
    if grid.min() < 0 or grid.max() > 1_000_000:
        raise ValueError("cells must be between 0 and 1000000")
    return width, height, steps, grid.astype(np.uint32)


def diffuse(width, height, steps, grid):
    """Run `steps` stencil steps on the GPU and return the resulting flat grid."""
    grid = np.ascontiguousarray(grid, dtype=np.uint32)
    if steps == 0:
        return grid.copy()

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    usage = (
        wgpu.BufferUsage.STORAGE
        | wgpu.BufferUsage.COPY_SRC
        | wgpu.BufferUsage.COPY_DST
    )
    buffers = [
        device.create_buffer_with_data(data=grid, usage=usage),
        device.create_buffer(size=grid.nbytes, usage=usage),
    ]
    dims = device.create_buffer_with_data(
        data=np.array([width, height], dtype=np.uint32),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    layout = pipeline.get_bind_group_layout(0)

    def bind_group(src, dst):
        return device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": dims}},
                {"binding": 1, "resource": {"buffer": src}},
                {"binding": 2, "resource": {"buffer": dst}},
            ],
        )

    groups = [bind_group(buffers[0], buffers[1]), bind_group(buffers[1], buffers[0])]
    gx = (width + WORKGROUP - 1) // WORKGROUP
    gy = (height + WORKGROUP - 1) // WORKGROUP

    encoder = device.create_command_encoder()
    for step in range(steps):
        # Each step is its own pass so it sees every write of the previous one.
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, groups[step % 2])
        compute.dispatch_workgroups(gx, gy, 1)
        compute.end()
    device.queue.submit([encoder.finish()])

    result = device.queue.read_buffer(buffers[steps % 2])
    return np.frombuffer(result, dtype=np.uint32).copy()


def render(width, height, grid):
    rows = grid.reshape(height, width)
    lines = [" ".join(map(str, row.tolist())) for row in rows]
    lines.append(f"SUM {int(grid.astype(np.int64).sum())}")
    return "\n".join(lines) + "\n"


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    try:
        with open(argv[1]) as f:
            width, height, steps, grid = parse(f.read())
    except (OSError, ValueError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    result = diffuse(width, height, steps, grid)
    sys.stdout.write(render(width, height, result))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

